const CACHE='inorganic-atlas-v10';
const SHELL=['./','index.html','lesson-01.html','lesson-02.html','lesson-03.html','lesson-04.html','terms.html','term.html','style.css','content.css','lesson.css','geometry.css','typography.css','script.js','qa.js','qa.css','data/terms.json','data/notes.json','assets/images/metal-multiple-bonding.webp','assets/images/quantum-numbers.webp','assets/images/radial-probability.webp','assets/images/d-f-orbitals.webp','assets/images/scn-formal-charge.webp','assets/images/vsepr-distortion.webp','assets/images/tbp-site-preference.webp','assets/images/lcp-model.webp','assets/images/symmetry-elements.webp','assets/images/bf3-rotation-axes.webp','assets/images/inversion-examples.webp','assets/images/improper-rotation.webp','assets/images/benzene-symmetry.webp','assets/images/linear-point-groups.webp','assets/images/platonic-groups.webp','assets/images/cnv-examples.webp','assets/images/benzene-d6h.webp','assets/images/dnd-examples.webp','assets/images/point-group-shapes.webp','assets/images/c2v-character-table.webp','assets/images/polarity-chirality.webp','assets/images/water-vibrations.webp','assets/images/cis-trans-carbonyl.webp','assets/images/exclusion-rule.webp'];
self.addEventListener('install',event=>event.waitUntil(caches.open(CACHE).then(cache=>cache.addAll(SHELL)).then(()=>self.skipWaiting())));
self.addEventListener('activate',event=>event.waitUntil(caches.keys().then(keys=>Promise.all(keys.filter(key=>key!==CACHE).map(key=>caches.delete(key)))).then(()=>self.clients.claim())));
self.addEventListener('fetch',event=>{
  if(event.request.method!=='GET'||new URL(event.request.url).origin!==location.origin)return;
  event.respondWith((async()=>{const cached=await caches.match(event.request);try{const response=await fetch(event.request);if(response.ok){const cache=await caches.open(CACHE);await cache.put(event.request,response.clone())}return response}catch{if(cached)return cached;if(event.request.mode==='navigate')return (await caches.match('index.html'))||new Response('<h1>暂时离线</h1><p>联网访问一次后即可离线阅读已缓存内容。</p>',{status:503,headers:{'Content-Type':'text/html; charset=utf-8'}});return new Response('',{status:503,statusText:'Offline'})}})());
});
